  /* ================= v5.4 (round 2, 14 Nov 2026): cleaner pages and NYC Open Data plugins =================
     - Map page: the City-vs-FLUSHING comparison moves to About (kept in the DOM, hidden, so the checks still read it).
     - Shortlists: three clearly separated sections (case studies, pick sites for me, more lists).
     - About and Method: a short, clean page on top; the long notes fold into "Detailed notes" at the bottom.
     - Throne pilot: explanations fold away; the check, maps and table stay.
     - Numbers › Testing the walk: a picture and a bar chart; the table folds away.
     - Unknowns becomes Changelog: one plain-text history of every version.
     - Open Data plugins: live layers for the lenses (Parks maintenance districts, licensed outdoor dining, health facilities). */
  const fold = (title, nodes, open) => { const d = document.createElement("details"); d.className = "v54notes"; if (open) d.open = true; d.innerHTML = `<summary>${title}</summary>`; nodes.forEach((n) => d.appendChild(n)); return d; };
  const kids = (el) => [...el.children];
  const byH = (root, re) => kids(root).find((n) => /^H[23]$/.test(n.tagName) && re.test(n.textContent));
  const untilNext = (start, stop) => { const out = []; let n = start; while (n && n !== stop) { out.push(n); n = n.nextElementSibling; } return out; };

  /* ---- deployment defaults: Numbers page rows for the calibrated cut-offs; data refresh switched on ---- */
  function deployDefaults() {
    // The cut-offs themselves are TH_PRESETS.dot in core/03_state_and_constants.js; this fills the Numbers page rows.
    if (typeof NUMS === "undefined") return;
    const row = (name, val, note) => { const r = NUMS.find((x) => x[2] === name && x[1] === "Number"); if (r) { r[3] = val; r[4] = "Calibrated"; r[5] = note; } };
    const why = "Calibrated to DOT's Pedestrian Demand Map: each tier is as rare across the city's blocks as the matching DOT street class.";
    row("Vulnerable residents", "24 / 28 / 37 / 43% → 2 / 3 / 4 / 5", why);
    row("Poverty", "8 / 13 / 28 / 41% → 2 / 3 / 4 / 5", why);
    row("Complaints", "0.3 / 0.5 / 1 / 2.5 a year within 200 m → 2 / 3 / 4 / 5", why);
    // the City's restroom list can be refreshed from NYC Open Data (the official source); the saved copy is for the team to publish
    ["rrPull", "rrLog", "rrSave"].forEach((id) => { const b = $(id); if (b) { b.classList.remove("v52gone"); if (id === "rrPull") { b.hidden = false; b.textContent = "Refresh from NYC Open Data"; } } });
  }

