    const bar = (v) => `${((v - 1) / 0.7) * 100}%`;
    const fig = document.createElement("div"); fig.className = "v54walk";
    fig.innerHTML = `<p class="v54lead">Nobody walks in a straight line, so the map stretches every straight line by <b>1.45</b>. We checked that number against 587 real walks routed on OpenStreetMap streets.</p>
<div class="v54walkfig">
<svg viewBox="0 0 240 170" role="img" aria-label="A straight line between a block and a restroom, and the longer walk along the streets"><g fill="none" stroke="var(--line,#ccd)" stroke-width="1">${[0, 1, 2, 3].map((r) => [0, 1, 2, 3].map((c) => `<rect x="${20 + c * 52}" y="${12 + r * 38}" width="40" height="28" rx="3"/>`).join("")).join("")}</g>
<path d="M30 30 L190 140" stroke="var(--muted,#5b6470)" stroke-width="2.5" stroke-dasharray="6 5" fill="none"/>
<path d="M30 30 L30 45 L66 45 L66 83 L118 83 L118 121 L170 121 L170 140 L190 140" stroke="#c2410c" stroke-width="4" fill="none" stroke-linejoin="round"/>
<circle cx="30" cy="30" r="7" fill="var(--ink,#111)"/><rect x="183" y="133" width="14" height="14" rx="2" fill="#2f7d4f"/>
<text x="38" y="22" font-size="11" fill="var(--ink,#111)">block</text><text x="150" y="162" font-size="11" fill="var(--ink,#111)">restroom</text></svg>
<div class="v54key2"><span><i style="border-top:3px dashed var(--muted,#5b6470)"></i>straight line</span><span><i style="border-top:4px solid #c2410c"></i>real walk ≈ 1.45 × longer</span></div>
</div>
<div class="v54bars"><div class="v54bh">Real walk ÷ straight line, walks of 300–800 m</div>${D4.map(([n, v]) => `<div class="v54br"><span>${n}</span><div class="t"><i style="width:${bar(v)}"></i><em style="left:${bar(1.45)}"></em></div><b>${v.toFixed(2)}</b></div>`).join("")}<p class="small">The line marks 1.45, the number the map uses everywhere. Staten Island needs about 1.59, so walks there look about 9% shorter than they are.</p></div>`;
