    const cases = $("v54cases"), h2s = kids(SL).filter((n) => n.tagName === "H2"), pickH = h2s.find((n) => /^Shortlists$/.test(n.textContent.trim())), moreH = h2s.find((n) => /More lists/i.test(n.textContent));
    const mk = (k, n, title, nodes) => { const s = document.createElement("section"); s.className = "v54sec"; s.innerHTML = `<p class="v54kick">${k} of 3</p>`; nodes.forEach((x) => s.appendChild(x)); return s; };
    const casesH = cases.querySelector("h2"); if (casesH) casesH.textContent = "Case studies";
